  'props.autoExtract': 'Išskleisti archyvus',
  'props.autoExtractHint': 'Ar archyvas išskleidžiamas, kai atsisiuntimas baigtas. „Paveldėti“ palieka sprendimą archyvų nustatymų puslapiui, o tai nėra tas pat kas išjungta. Jungiklis skaitomas išskleidimo metu, tad įjungęs jį dabar išskleisi ir tai, kas baigėsi anksčiau.',
