  'settings.scripts.trigger': 'Vykdomas, kai',
  'settings.scripts.triggerHint':
    'Kas paleidžia šį skriptą. Rankinis vykdomas tik tada, kai jūs to paprašote - iš žemiau esančio Bandomojo paleidimo arba iš punkto „Vykdyti skriptą“, kurį ši banga prideda prie atsisiuntimų sąrašo dešiniojo klavišo meniu.',
