  'settings.access.ownRelay.containerLabel': 'Kaip atskiras konteineris',
  'settings.access.ownRelay.containerHint': 'Jei nė vienas tavo egzempliorius nepasiekiamas iš išorės, relė turi stovėti kitur: tavo serveryje arba mažame VPS. Įdiek konteinerį iš Unraid Community Applications arba žemiau esančia komanda.\n\nKonteineriui nereikia jokių nustatymų: paleisk, viršuje įrašyk jo adresą, ir viskas. Jis nieko nesaugo, tad nėra ko atsarginiu kopijuoti.',
