  'settings.access.identity.namePlaceholder': 'pvz., Namų serveris',
  'settings.access.identity.nameHint': 'Siūlomas pirmiausia porinant ir toliau esančiame QR kode, o ne tuo, kaip operacinė sistema ar konteinerio vykdymo aplinka atsitiktinai vadina šį kompiuterį. Nebūtina - palikite tuščią, kad būtų naudojamas tas pavadinimas.',
  'settings.access.identity.domainsLabel': 'Žinomi domenai',
  'settings.access.identity.domainsHint': 'Automatiškai įsimenamas, kai per jį pirmą kartą tikrai atkeliauja užklausa, todėl jis lieka čia rodomas net kai vėlesnės užklausos atkeliauja per LAN IP. Pridėkite vieną rankiniu būdu domenui, kuris jau sukonfigūruotas, bet dar nebuvo aplankytas - vienas pilnas adresas eilutėje, pvz., https://kl.example.com.',
  'settings.access.cardTitle': 'Sujungti egzempliorius ir nuotolinė prieiga',
  'settings.access.phrase.body': 'Viena frazė sujungia visus jūsų KnightLoader. Sukurkite ją čia ir įklijuokite į kitus egzempliorius - be paskyros, be prisijungimo, nieko nereikia konfigūruoti.',
  'settings.access.phrase.noPasswordWarning': 'Šis egzempliorius neturi slaptažodžio. Frazė pasiekia kiekvieną su ja sujungtą egzempliorių, tad kas ją čia perskaitys, pasieks visus, ne tik šį. Geriau pirma nustatykite slaptažodį viršuje.',
  'settings.access.phrase.activate': 'Sukurti frazę',
  'settings.access.phrase.howLead': 'Dvylika žodžių, daugiau nereikia. Štai kaip ir kas vyksta:',
  'settings.access.phrase.howStep1': 'Šiame egzemplioriuje spausk „{button}“. Pasirodo dvylika žodžių.',
  'settings.access.phrase.howStep2': 'Atverk KnightLoader kitame įrenginyje, eik į šį patį puslapį, spausk „{button}“ ir įrašyk dvylika žodžių.',
  'settings.access.phrase.howStep3': 'Baigta! Kiekvienas egzempliorius dabar rodomas kito skiltyje „Egzemplioriai“, ir gali valdyti bet kurį iš bet kurio. Įjungus relę, tavo egzemplioriai pasiekiami ir iš išorės.',
  'settings.access.phrase.howWhat': 'Žodžiai yra paslaptis, o ne adresas. Kiekvienas egzempliorius iš jų apskaičiuoja du raktus: vieną kitiems surasti, kitą šifruoti.\n\nKad susirastų, kiekvienas egzempliorius pats skambina į tą pačią susitikimo vietą internete. Kas parodo tą patį raktą, tas sujungiamas. Todėl nė vienas tavo egzempliorius neprivalo būti pasiekiamas iš išorės.\n\nSusitikimo vieta skaityti negali. Tavo žodžių ji niekada nemato, o viskas, kas per ją eina, užšifruota antruoju raktu.',
