  'settings.resolvers.intro': 'yt-dlp serverinės dalies konfigūracija - ji parsisiunčia iš medijos ir transliavimo svetainių, kurias palaiko pats yt-dlp. Kuri paslauga apskritai apdoroja konkrečią nuorodą - yt-dlp, debrid paskyra, be sąsajos veikiantis JD priedas - nustatoma pagal maršruto tvarką puslapyje Paskyros; čia aprašoma tik tai, ką yt-dlp daro, kai nuoroda jau nukreipta į jį.',
