  'settings.torrents.portMapUnconfirmed': 'Maršrutizatorius priėmė prašymą, bet nepavyko patvirtinti, ar nukreipimas iš tikrųjų veikia. Kai kurie maršrutizatoriai tai daro tyliai - pabandykite ryšio patikrą iš už tinklo ribų.',
  'settings.torrents.portMapFailed': 'Nepavyko nukreipti prievado: {error}',
  'settings.torrents.portMapUnavailable': 'Ši versija dar nesiūlo prievado nukreipimo.',
  'settings.torrents.networkTitle': "Peer'ų paieška",
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': "Randa peer'ų be jokio sekiklio, naudodamas kitus BitTorrent klientus kaip paskirstytą sąrašą.",
  'settings.torrents.pex': "Peer'ų mainai (PEX)",
  'settings.torrents.pexHint': "Keičiasi žinomais peer'iais su jau prisijungusiais, kad spiečius su mažai peer'ų būtų rastas greičiau.",
  'settings.torrents.privateNote': 'Privatus torrentas automatiškai išjungia abu, kai tik tampa žinomi jo metaduomenys, nepaisant čia nustatyto - įkeltam .torrent failui iš karto, o magnet nuorodai - kai tik jos pačios metaduomenys atkeliauja iš spiečiaus. Dauguma privačių sekiklių draudžia paskyras, naudojančias bet kurį iš jų.',
  'settings.torrents.engineNote': 'Tikslinis sėjimo santykis, tikslinė sėjimo trukmė ir prievadas dabar pasiekia kiekvieną torrentą, kurį paleidžia šis variklis - prievadas tik pirmajam torrentui nuo paskutinio šio egzemplioriaus paleidimo iš naujo, nes paties variklio torrentų klientas sukuriamas tik vieną kartą ir vėliau niekada nebeperkuriamas; vėlesnis išsaugojimas vis tiek išsaugomas teisingai ir įsigalioja nuo kito paleidimo iš naujo. Siuntimo riba kol kas tik išsaugoma ir patikrinama, o varikliui dar nėra kaip pritaikyti jos vykstančiam atsisiuntimui. Žemiau esantys DHT ir PEX paprastam (neprivačiam) torrentui yra tokioje pačioje padėtyje: šio egzemplioriaus numatytoji reikšmė taip pat dar nepasiekia vykstančio atsisiuntimo, todėl torrentas ir toliau sėjamas su abiem įjungtais, nepaisant čia nustatyto - privatus torrentas yra visai kitas atvejis, žr. žemiau esančią pastabą. Vis dėlto žemiau esantis nukreipimo mygtukas atlieka kai ką tikro: jis sąžiningai prašo maršrutizatoriaus nukreipti aukščiau įvestą prievado numerį, nesvarbu, ar jį šiuo metu klauso koks nors torrentas, ar ne.',
  'torrent.staging': 'Pridedama…',
  'torrent.staged': '{file} pridėtas į rinktuvą.',
  'torrent.stagedIn': '{file} pridėtas į rinktuvą „{pkg}“.',
