  'onboarding.step': '{n} veiksmas iš {total}',
  'onboarding.skip': 'Praleisti',
  'onboarding.back': 'Atgal',
  'onboarding.next': 'Toliau',
  'onboarding.finish': 'Pradėti naudoti KnightLoader',
  'onboarding.welcome.title': 'Sveiki atvykę į KnightLoader',
  'onboarding.welcome.body': 'KnightLoader yra savarankiškai talpinama atsisiuntimų tvarkyklė: įklijuok arba numesk nuorodą, ir ją paims tas backend’as, kuris iš tikrųjų ją tvarko - integruotas variklis paprastoms failų nuorodoms, yt-dlp medijos puslapiams, debrid paslauga hosteriams, už kuriuos jau moki, arba JDownloader be sąsajos viskam kitam. Šis trumpas turas apžvelgia vienintelį nustatymą, kurį verta patikrinti prieš pradedant.',
  'onboarding.welcome.langLabel': 'Sąsajos kalba',
  'onboarding.folder.title': 'Kur turėtų atsidurti failai?',
  'onboarding.folder.body': 'Tai aplankas, į kurį rašomi baigti atsisiuntimai. Įvesk kelią arba naršyk serverį, kad jį pasirinktum - gali jį vėl pakeisti bet kada Bendruosiuose nustatymuose.',
  'onboarding.accounts.title': 'Premium hosteriai, kada tik panorėsi',
  'onboarding.accounts.body': 'Eilė veikia visiškai be paskyros. Kai panorėsi pilno greičio pas hosterį ar debrid paslaugą, už kurią jau moki, pridėk jos prisijungimą Paskyrose - čia dabar nieko konfigūruoti nereikia.',
  'onboarding.accounts.link': 'Atverti Paskyras',
  'onboarding.finished.title': 'Viskas paruošta',
  'onboarding.finished.body': 'Tuo turas ir baigiasi. Pagalbos puslapyje, esančiame Nustatymuose, rasi pilną visko kito, ką ši versija daro, apžvalgą, o dauguma valdiklių turi savo paaiškinimą už (i) ženkliuko.',

