  'settings.downloads.diskTitle': 'Vieta diske',
  'settings.downloads.diskHint': 'Trys skaičiai, kurie sulaiko atsisiuntimus prieš diskui prisipildant, o ne po to. Visi trys reiškia laisvus baitus tame diske, į kurį atsisiuntimas rašomas, tad kitame diske esantis darbinis aplankas matuojamas ten. Nulis atitinkamą skaičių išjungia. Ko tai negali: ne kiekvienos sistemos galima paklausti, kiek vietos laisva, o ten, kur atsakymo nėra, niekada niekas nesulaikoma, nes sargas, blokuojantis nežinodamas, sustabdytų visiškai sveiką mašiną.',
