  'settings.headerProfiles.title': 'Antraščių profiliai',
  'settings.headerProfiles.hint': 'Kai kurios svetainės failą atiduoda tik prisijungusiai naršyklei arba tik tada, kai kreipiamasi iš vieno jų pačių puslapio. Profilis saugo antraštes lygiai vienai svetainei, užrakintas taip pat kaip tavo prisijungimo duomenys, ir KnightLoader jas siunčia su kiekvienu atsisiuntimu iš tos svetainės.',
  'settings.headerProfiles.empty': 'Antraščių profilių dar nėra.',
  'settings.headerProfiles.emptyHint': 'Vieną verta turėti, kai tik atsisiuntimas pavyksta tik tol, kol esi prisijungęs naršyklėje.',
