  'settings.rules.action.category': 'Kategorija',
  'settings.rules.action.categoryHint': 'Sudeda atitinkančias nuorodas į vieną iš Kategorijų puslapio stalčių, o tas atsineša savo aplanką, savo vietą eilėje, savo išpakavimo jungiklį ir savo taisyklę failui, kuris jau yra. Palikus nepakeista, nė viena taisyklė apie tai nieko nesako ir nuoroda lieka niekur nesudėta. Jei ši taisyklė nurodo dar ir atsisiuntimų aplanką, laimi tas aplankas, o stalčius vis tiek duoda visa kita. Nurodyti ištrintą stalčių įrašant neleidžiama, nes taisyklė, rodanti į stalčių, kurio nėra, su kiekviena atitinkančia nuoroda tyliai nedaro visiškai nieko.',
  'settings.rules.action.categoryNone': 'Kategorijų dar nėra. Pirma susikurk vieną Kategorijų puslapyje, kitaip ši taisyklė dėtų nuorodas į stalčių, kurio nėra.',
  'settings.rules.action.categoryMissing': '{id} (ištrintas)',

