  'detail.label': 'Užduoties informacija',
  'detail.link': 'Nuoroda',
  'detail.address': 'Adresas',
  'detail.addressHint': 'Adresas, kuriuo šis atsisiuntimas buvo paleistas. Būtent to programa ir paprašė, o tai ne visada ta vieta, iš kurios atėjo baitai: per debrid paslaugą žemiau nurodyta talpykla yra svetainė, kurioje guli failas, o posistemė yra tas, kuris jį parsiuntė.',
  'detail.copy': 'Kopijuoti',
