  'detail.package': 'Paketas',
  'detail.noPackage': 'Be paketo',
  'detail.onDisk': 'Šiuo metu diske',
  'detail.onDiskHint': 'Kiek failas šią sekundę sveria diske, paklausus serverio, o ne suskaičiavus čia. Vykstantis atsisiuntimas tarp dviejų žvilgsnių paauga, ir tai nėra tas dydis, kurį paskelbė talpykla.',
  'detail.mirrorOf': 'Atsarginė kopija',
  'detail.times': 'Laiko žymos',
  'detail.timesHint': 'Kada ši nuoroda atkeliavo, kada paskutinį kartą pasikeitė ir kada nusistovėjo. Kada prasidėjo perdavimas, čia nerasi: programa to niekada neužrašo, o iš kitų trijų atspėtas laikas būtų skaičius, pagal kurį žmonės imtų elgtis.',
  'detail.nextTry': 'Kitas bandymas',
  'detail.stalledSince': 'Stovi nuo',
  'detail.retries': 'Pakartojimų iki šiol',
  'detail.retriesHint': 'Kiek kartų šis atsisiuntimas po nesėkmės buvo bandytas dar kartą. Vos jis baigiamas, skaitiklis nunulinamas, tad baigta eilutė rodo nulį net tada, kai prireikė keturių bandymų. Kiek bandymų dar liko, čia nerodoma: viršutinė riba priklauso nuo priežasties ir nuo talpyklos, ir šis puslapis jos apskaičiuoti negali.',
  'detail.stallRestarts': 'Paleidimai iš naujo po sustojimo',
  'detail.stallRestartsHint': 'Kiek kartų sustojimų sargas pats iš naujo paleido šį atsisiuntimą. Atsisiuntimui pasibaigus nunulinamas, lygiai kaip skaitiklis viršuje.',
  'detail.failure': 'Kas nepavyko',
  'detail.cause': 'Priežastis',
  'detail.message': 'Ką pasakė posistemė',
  'detail.messageHint': 'Sakinys iš to, kas bandė tai parsiųsti, žodis į žodį ir neišverstas. Tai dabartinė klaida ir nieko daugiau: paleidus iš naujo ji išvaloma, o ankstesnės niekur nesaugomos.',
  'detail.heldBack': 'Sulaiko',
  'detail.doing': 'Šiuo metu vyksta',
  'detail.filtered': 'Sulaikė nuorodų filtras',
  'detail.gaveUp': 'Daugiau nebebandoma',
  'detail.gaveUpHint': 'Čia sustota sąmoningai, o ne todėl, kad baigėsi bandymai: captcha, pilnas diskas arba taisyklė, kuri šiai talpyklai sako „niekada“. Pakartojimų skaičiaus didinimas čia nieko nekeičia. Pati žyma į duomenų bazę nerašoma, tad po paleidimo iš naujo jos nebelieka, nors jos priežastis lieka.',
  'detail.rules': 'Taisyklės, kurios tai suformavo',
  'detail.rulesHint': 'Taisyklės, kurios suveikė šiai nuorodai ją paruošiant, ta pačia eile, kuria veikė. Užduotyje jos saugomos pagal pavadinimą: nuo tada pervadintos taisyklės nebepavyksta rasti, o taisyklė, kuri pavadinimo niekada neturėjo, saugoma su ta vieta, kurią tuomet užėmė. Spustelėjus ji atveriama taisyklių rengyklėje.',
  'detail.openRule': 'Atverti taisyklių rengyklėje',
  'detail.noRules': 'Šios nuorodos nepalietė nė viena taisyklė.',
  'detail.player': 'Leisti',
  'detail.play': 'Leisti čia',
  'detail.playHint': 'Leidžia failą tiesiai iš šio egzemplioriaus, nesiunčiant jo antrą kartą. Kol nepaspaudi leisti, nieko neparsiunčiama, o failas lieka ten, kur yra.',
  'detail.playPartial': 'Šis atsisiuntimas nebaigtas. Leisti galima tik tą dalį, kuri jau yra diske, peršokti toliau nepavyks, o kai kurie failai nepaleidžia visai nieko, kol neatkeliauja paskutinis baitas.',
  'detail.playUnsupported': 'Ši naršyklė šio failo leisti negali. Atverk arba išsaugok jį per dešiniojo klavišo meniu.',
  'detail.playRemote': 'Čia leidžiami tik šio egzemplioriaus failai. Kitas egzempliorius savo failus atiduoda vientisai ir be šokinėjimo, o su tuo grotuvas nesusitvarko.',
  'detail.playNotLocal': 'Šį atsisiuntimą parsiuntė JDownloader, tad failas guli to proceso diske, o ne šiame.',
  'detail.playNoFile': 'Diske dar nėra ko leisti.',
