  'settings.rules.notFound': 'Čia nėra taisyklės pavadinimu „{name}“. Ji buvo pervadinta arba ištrinta po to, kai buvo pridėta ją įvardijanti nuoroda.',

  'notifications.title': 'Pranešimai',
  'notifications.titleHint': 'Kiekvienam įvykiui nuspręsk, ar jis rodomas kaip burbulas programoje, kaip operacinės sistemos pranešimas, ar visai nerodomas. Sistemos pranešimas tave pasiekia tik tol, kol atidarytas KnightLoader skirtukas, o žemiau esantis tylusis režimas galioja papildomai.',
  'notifications.channel.app': 'Programoje',
  'notifications.channel.system': 'Sistemos pranešimas',
  'notifications.channel.silent': 'Nerodyti nieko',
  'notifications.event.downloadDone': 'Atsisiuntimas baigtas',
  'notifications.event.downloadDoneHint': 'Kiekvienas iki galo atėjęs atsisiuntimas apie tai praneša. Du šimtai failų eilėje reiškia du šimtus tokių pranešimų, tad gerai pagalvok, ar siųsti juos sistemai.',
  'notifications.event.downloadFailed': 'Atsisiuntimas nepavyko',
  'notifications.event.downloadFailedHint': 'Atsisiuntimas, kuris pasidavė. Tylusis režimas šito niekada neslepia.',
  'notifications.event.extractionDone': 'Išpakavimas baigtas',
  'notifications.event.extractionDoneHint': 'Archyvas, kuris baigtas išpakuoti. Anksčiau apie tai niekas nepranešdavo, tad iš pradžių nustatyta „Nerodyti nieko“.',
  'notifications.event.extractionFailed': 'Išpakavimas nepavyko',
  'notifications.event.extractionFailedHint': 'Archyvas, kuris nutrūko nebaigtas. Dažniausiai trūksta slaptažodžio, o failai lieka gulėti, kol tuo pasirūpini.',
  'notifications.event.captchaWaiting': 'Captcha laukia',
  'notifications.event.captchaWaitingHint': 'Captcha langas šiame skirtuke atsiveria šiaip ar taip. Iš pradžių nustatyta „Nerodyti nieko“, nes, kol į jį žiūri, tas langas jau ir yra pranešimas. Nustatyk sistemos pranešimą, ir captcha fone atvertame skirtuke pasieks tave dar prieš talpyklai nutraukiant sesiją.',
  'notifications.event.captchaFailed': 'Captcha nepavyko',
  'notifications.event.captchaFailedHint': 'Niekas neatsakė laiku arba atsakymas nepraėjo. Už jos stovintis atsisiuntimas lieka gulėti.',
  'notifications.event.captchaResolved': 'Captcha išspręsta kitur',
  'notifications.event.captchaResolvedHint': 'Kažkas kitoje naršyklėje arba automatinis sprendėjas ją išsprendė, ir langas užsivėrė pats.',
  'notifications.systemUnavailable': 'Sistemos pranešimų čia nėra: naršyklė juos siūlo tik per HTTPS arba localhost. Viskas, kas yra šioje kortelėje, vis tiek rodoma programoje.',
  'notifications.systemBlocked': 'Naršyklė blokuoja pranešimus šiam adresui. Eilutės, kurioms nustatyta „Sistemos pranešimas“, rodomos programoje tol, kol naršyklės svetainės nustatymuose jų vėl neleisi.',
  'notifications.systemNotGranted': 'Naršyklė leidimo nedavė, tad šis įvykis lieka programoje. Pasirink „Sistemos pranešimas“ dar kartą, kad būtų paklausta iš naujo.',
