  'views.clearAllHint': 'Paieška ir filtrai lieka nustatyti, kai išeini iš šio puslapio ir grįžti, tad matai tą patį sąrašą, kurį palikai. Šitas grąžina visą sąrašą. Įrašyti rodiniai lieka nepaliesti.',

  'disk.title': 'Paskirties aplankai',
  'disk.hint': 'Laisva ir užimta vieta kiekviename aplanke, į kurį gali nusileisti atsisiuntimas, ir kiek eilė į kiekvieną iš jų dar turi įrašyti. Skaičiai imami iš tos pačios užklausos, pagal kurią tikrinamos ir disko ribos, ir yra daugiausia kelių sekundžių senumo. Laisva ir užimta ne visada susideda į disko dydį: failų sistema dalį pasilieka sistemai, o naudotojui skirta kvota gali palikti šiam egzemplioriui mažiau, nei diskas iš tikrųjų turi. Du aplankai tame pačiame diske rodo tą patį diską, tad niekada nesudėk eilučių.',
  'disk.free': 'Laisva',
  'disk.used': 'Užimta',
  'disk.size': 'Disko dydis',
  'disk.queued': 'Dar bus įrašyta',
  'disk.queuedHint': 'Kiek dar neatlikti atsisiuntimai pridėtų į šį aplanką: talpyklos paskelbtas dydis be to, kas jau atkeliavo. Atsisiuntimas, kurio dydžio talpykla nepasako, čia skaičiuojamas kaip nulis, tad tai apatinė riba, o ne pažadas, ir būtent todėl šalia eilės atsisiuntimų gali stovėti nulis baitų. Išjungti atsisiuntimai lieka už skaičiaus ribų, ta pati taisyklė galioja ir skaitikliams po sąrašu. Jau vykstančiam atsisiuntimui vieta diske dažniausiai atidedama tą pačią akimirką, kai jis prasideda, tad jo baitų šalia esančiame laisvos vietos skaičiuje jau trūksta, ir jie neprisideda dar kartą.',
  'disk.tasks': 'atsisiuntimų: {n}',
  'disk.unknown': 'Ši sistema nepraneša, kiek vietos laisva',
  'disk.unknownHint': 'Ne kiekvieno branduolio galima paklausti, kiek diske liko vietos, o ši laida tam, ant kurio veikia, tinkamo kreipinio neturi. Kur atsakymo nėra, niekas nesulaikoma: atsisiuntimai prasideda lygiai taip, kaip prieš atsirandant disko riboms. Ši eilutė čia tam, kad tai atskirtum nuo iš tikrųjų pilno disko.',
  'disk.missing': 'Dar nesukurtas',
  'disk.missingHint': 'Šį aplanką sukuria tas, kas įrašo į jį pirmą failą, tad jo dar nėra. Skaičiai aprašo {path}, artimiausią esamą aplanką virš jo, o šis guli tame diske, į kurį nusileistų atsisiuntimas.',
  'disk.measured': 'Išmatuota ties {path}',
  'disk.elsewhereHint': 'Paties aplanko išmatuoti nepavyko, tad matuotas artimiausias esantis aplankas virš jo. Jei koks prijungimas nepakilo, tai gali būti visai kitas diskas nei tas, kuriam skirtas atsisiuntimas. Pirma pasižiūrėk kelią, tik paskui ką nors spręsk iš skaičių.',
  'disk.sampled': 'Nuskaityta prieš {n} s',
  'disk.tight': 'Eilė netelpa',
  'disk.tightHint': 'Į šį aplanką žadama įrašyti daugiau, nei diske yra laisva. Ši eilutė pati nieko nestabdo: sulaikoma po vieną, kai ateina to atsisiuntimo eilė, pagal skaičius Atsisiuntimų nustatymų puslapyje, o atsisiuntimas, kurio dydžio niekas nežino, čia išvis neskaičiuojamas.',
  'disk.truncated': 'Čia surašyti ne visi aplankai',
  'disk.truncatedHint': 'Eilė taikosi į daugiau aplankų už nustatytųjų ribų, nei apsimoka matuoti per kiekvieną nuskaitymą, tad tie, kuriems skirta mažiausiai, praleisti. Kiekvienas tavo nustatytas aplankas čia yra visada.',
  'disk.markLow': 'Žemiau šios ribos niekas naujo nebepradedama',
  'disk.markStop': 'Žemiau šios ribos viskas stabdoma',
  'disk.limits': 'Nustatyti disko ribas',
  'disk.stripLabel': 'Vieta paskirties aplankuose',
  'disk.role.downloads': 'Atsisiuntimų aplankas',
  'disk.role.category': 'Kategorijos aplankas',
  'disk.role.work': 'Darbinis aplankas',
  'disk.role.task': 'Nustatyta ties pačiu atsisiuntimu',

  'settings.volume.title': 'Duomenų kiekio riba',
  'settings.volume.titleHint': 'Kiek šis egzempliorius baigė atsisiųsti, lyginant su tavo nustatyta riba per laikotarpį. Skaičiuojamas dydis, kurį talpykla paskelbė kiekvienam baigtam atsisiuntimui, tad viskas, kas baigėsi be nurodyto dydžio, skaičiuojama kaip nulis, o tai, ką išsiunčia torentas, neskaičiuojama visai. Tai tavo atsisiuntimų suvestinė, o ne tavo linijos matavimas: kiek baitų iš tikrųjų perkėlė tavo maršrutizatorius, čia nemato niekas.',
  'settings.volume.cap': 'Riba per laikotarpį (GB)',
  'settings.volume.capHint': '0 reiškia, kad ribos nėra: skaitiklis toliau sukasi ir niekas niekada nesulaikoma. Gigabaitai čia dešimtainiai, taip, kaip savo kiekį nurodo paslaugos teikėjas, tad 500 GB yra 500 000 000 000 baitų, o ne 465 GiB. Disko slenksčiai aukščiau šiame puslapyje yra dvejetainiai GiB, o tai kitas vienetas kitam klausimui.',
  'settings.volume.resetDay': 'Skaitiklis pradedamas iš naujo (mėnesio diena)',
  'settings.volume.resetDayHint': 'Mėnesio diena, kurią skaitiklis vėl pradedamas nuo nulio, dažniausiai ta, kurią atnaujinamas tavo kiekis. Mėnesį, kuris trumpesnis už pasirinktą dieną, jis pradedamas iš naujo paskutinę to mėnesio dieną ir niekada nenuslysta į kitą. Skaičiuojama pagal serverio, o ne tavo naršyklės laikrodį, nes eilę sulaiko būtent serveris.',
  'settings.volume.action': 'Kai riba pasiekiama',
  'settings.volume.actionHint': 'Jau vykstantis perdavimas niekada nenutraukiamas, kad ir ką pasirinktum: nutraukus failo viduryje išmetami baitai, kuriuos jau išleidai. „Tik pranešti“ nieko nekeičia, tada skaitiklis ir yra visa funkcija. „Nebepradėti atsisiuntimų“ leidžia baigti tam, kas vyksta, ir sulaiko eilę, kol skaitiklis pradedamas iš naujo; kiekviena laukianti eilutė tai ir pasako. „Viską sulėtinti“ palieka eilę veikti žemiau nurodytu greičiu.',
  'settings.volume.actionReport': 'Tik pranešti',
  'settings.volume.actionPause': 'Nebepradėti atsisiuntimų',
  'settings.volume.actionThrottle': 'Viską sulėtinti',
  'settings.volume.throttle': 'Greitis pasiekus ribą (KiB/s)',
  'settings.volume.throttleHint': 'Greitis, galiojantis likusiai laikotarpio daliai. Tai viršutinė riba šalia kitų tavo ribų, o niekada ne vietoj jų: naktinis langas ar tylusis jungiklis, prašantys mažiau, ir toliau laimi. 0 čia reikštų, kad ribos nėra visai, o tai tas pat, kas neturėti ribos, tad mažiausias prasmingas skaičius yra 1.',
  'settings.volume.noCap': 'Ribos nėra',
  'settings.volume.used': 'Šiuo laikotarpiu atsisiųsta',
  'settings.volume.usedOf': '{used} iš {cap}',
  'settings.volume.resetsOn': 'Iš naujo pradedama {date}',
  'settings.volume.reached': 'Riba pasiekta.',

  'volume.title': 'Atsisiųstas kiekis',
  'volume.titleHint': 'Baigti atsisiuntimai, sudėti pagal dienas ir pagal mėnesius, iš atsisiuntimų istorijos. Istorija turi savo pačios ribą ir gali būti ištuštinta ranka, tad mėnesių, iškritusių iš jos galo, čia paprasčiausiai nėra. Iš naujo paleistas atsisiuntimas skaičiuojamas vieną kartą, tą dieną, kurią jis paskutinį kartą baigėsi. Skaičiuojama pagal serverio kalendorių, juosta {zone}.',
  'volume.range.days': '30 dienų',
  'volume.range.months': '12 mėnesių',
  'volume.split.total': 'Viskas',
  'volume.split.host': 'Pagal talpyklą',
  'volume.split.backend': 'Pagal posistemę',
  'volume.other': 'Visa kita',
  'volume.empty': 'Šiuo laikotarpiu dar niekas nebaigta.',
  'volume.unsizedHint': 'Šių atsisiuntimų {n} baigėsi taip ir nesulaukę talpyklos nurodyto dydžio. Prie sumos jie nieko neprideda, tad tikrasis skaičius didesnis už čia nubraižytą.',
  'volume.trimmedHint': 'Istorija pasiekė savo pačios ribą, tad viskas, kas senesnis už seniausią jos įrašą, dingsta ir iš šios kreivės. Jei nori ilgesnio įrašo, šiame puslapyje pakelk istorijos ribą.',
  'volume.meter': 'Duomenų kiekis',
  'volume.meterHint': 'Kiek baigta atsisiųsti nuo tada, kai skaitiklis paskutinį kartą pradėtas iš naujo, lyginant su riba Atsisiuntimų nustatymų puslapyje. Skaičius pajuda, kai atsisiuntimas baigiamas, o ne kol jis vyksta: jis šokteli, o ne šliaužia. Jis sudedamas iš atsisiuntimų istorijos, tad ištuštinęs tą istoriją nunulini ir šį skaitiklį.',

