  'settings.resolvers.toolsFrom.path': 'Found on PATH',
  'settings.resolvers.toolsFrom.none': 'Nowhere',
  'settings.resolvers.toolsYtdlpMissingHint': 'Without yt-dlp there is no media backend at all: a link to a video page is refused with the site\'s own error instead of being downloaded. In the container it comes from the image\'s yt-dlp package; on the desktop you install it yourself and either put it on PATH or point KL_YTDLP at it. The button below fetches a copy on its own if neither is an option.',
  'settings.resolvers.toolsFfmpegMissingHint': 'Without ffmpeg, yt-dlp cannot join the separate picture and sound tracks that most sites hand out, so a download either lands as a silent video track or fails outright. Without ffprobe, "Check the finished file" further up this page measures nothing and says nothing about it. In the container both come from the ffmpeg package the image installs; on the desktop you install them yourself and put them on PATH.',
  'settings.resolvers.toolsShadowed': 'KnightLoader\'s own copy is running. KL_YTDLP and PATH are not being started while it is there: {path} would be used instead, and it reports {version}.',
  'settings.resolvers.toolsShadowedOlder': 'Careful: the copy KnightLoader fetched ({current}) is older than the one already on this machine ({system}, at {path}). A container update brings a newer yt-dlp with it, and your own copy does not move with it. Fetch a new one, or go back to the system copy.',
  'settings.resolvers.toolsManagedBroken': 'A fetched copy is recorded at {path} and it does not start. What is running instead is the fallback shown above. Fetch it again, or go back to the system copy.',
  'settings.resolvers.toolsActions': 'Keeping yt-dlp current',
  'settings.resolvers.toolsActionsHint': 'Fetching downloads yt-dlp from github.com, checks it against the SHA2-256SUMS file published in the same release, starts it once to see that it runs on this machine at all, and only then puts it next to your data, where KnightLoader starts it from. Until that last step the copy you already had keeps working, and your system\'s own yt-dlp is never touched.',
  'settings.resolvers.toolsCheck': 'Ask GitHub',
